+describe('given a Slot that re-renders (React 19 ref behavior)', () => {
+  afterEach(cleanup);
+
+  // Regression: https://github.com/radix-ui/primitives/issues (Maximum update depth exceeded).
+  // In React 19 a ref callback whose identity changes between renders is detached (called with
+  // `null`) and re-attached. If the Slot re-created its composed ref on every render and a
+  // function ref scheduled state updates, this detached/attached in a loop. The composed ref
+  // must be stable across re-renders.
+  it('does not throw "Maximum update depth exceeded" when a function ref schedules updates', async () => {
+    const errorSpy = vi.spyOn(console, 'error').mockImplementation(() => {});
+
+    function Repro() {
+      const [text, setText] = React.useState('');
+      const ref = React.useCallback((_node: HTMLButtonElement | null) => {
+        setText((t) => t + '!');
+      }, []);
+
+      return (
+        <div>
+          <input value={text} onChange={(e) => setText(e.target.value)} />
+          <Slot ref={ref}>
+            <button type="button">hi</button>
+          </Slot>
+        </div>
+      );
+    }
+
+    render(<Repro />);
+    await userEvent.type(screen.getByRole('textbox'), 'a');
+
