+NavigationMenuTrigger.displayName = TRIGGER_NAME;
+
+/* -------------------------------------------------------------------------------------------------
+ * NavigationMenuLink
+ * -----------------------------------------------------------------------------------------------*/
+
+const LINK_NAME = 'NavigationMenuLink';
+const LINK_SELECT = 'navigationMenu.linkSelect';
