+/* -------------------------------------------------------------------------------------------------
+ * NavigationMenuIndicator
+ * -----------------------------------------------------------------------------------------------*/
+
+const INDICATOR_NAME = 'NavigationMenuIndicator';
+
+type NavigationMenuIndicatorElement = NavigationMenuIndicatorImplElement;
