+NavigationMenuIndicator.displayName = INDICATOR_NAME;
+
+type NavigationMenuIndicatorImplElement = React.ComponentRef<typeof Primitive.div>;
+interface NavigationMenuIndicatorImplProps extends PrimitiveDivProps {}
