+const NavigationMenuIndicatorImpl = React.forwardRef<
+  NavigationMenuIndicatorImplElement,
+  NavigationMenuIndicatorImplProps
+>((props: ScopedProps<NavigationMenuIndicatorImplProps>, forwardedRef) => {
