NavigationMenuViewport.displayName = VIEWPORT_NAME;

/* -----------------------------------------------------------------------------------------------*/

interface NavigationMenuViewportContentProps extends NavigationMenuContentImplProps {
  forceMount?: true;
  isActive: boolean;
  itemRef: React.Ref<NavigationMenuContentElement>;
  onContentChange(node: NavigationMenuContentElement | null): void;
}

const NavigationMenuViewportContent = (
  props: ScopedProps<NavigationMenuViewportContentProps>,
) => {
  const {
    __scopeNavigationMenu,
    forceMount,
    isActive,
    itemRef,
    onContentChange,
    ...contentProps
  } = props;
  // Memoize the composed ref: an unstable ref callback makes React 19 detach and
  // re-attach the ref on every render, which can loop when a function ref schedules
  // state updates (see the Slot "Maximum update depth exceeded" bug). The inner
  // callback stays stable via `useCallbackRef` while still reading fresh values.
  const composedRefs = useComposedRefs(
    itemRef,
    useCallbackRef((node: NavigationMenuContentElement | null) => {
      // We only want to update the stored node when another is available
      // as we need to smoothly transition between them.
      if (isActive && node) onContentChange(node);
    }),
  );

  return (
    <Presence present={forceMount || isActive}>
      <NavigationMenuContentImpl
        {...contentProps}
        __scopeNavigationMenu={__scopeNavigationMenu}
        ref={composedRefs}
      />
    </Presence>
  );
};

/* -----------------------------------------------------------------------------------------------*/

